def topological_sort(graph):
    visited = set()
    visiting = set()
    order = []

    def visit(node):
        if node in visited:
            return
        if node in visiting:
            raise ValueError('cycle detected')
        visiting.add(node)
        for dependency in graph.get(node, []):
            visit(dependency)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in graph:
        visit(node)
    return order
